package com.shengyu.framework.netty.config;import com.shengyu.framework.netty.core.NettyServer;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;/** * 网络通讯配置类 * @author zhusy * @since 2022/11/12 */@Configuration@EnableConfigurationProperties(NettyProperties.class)public class ShengyuNettyAutoConfiguration {    @Bean    public NettyServer nettyServer(NettyProperties nettyProperties) {        return new NettyServer(nettyProperties);    }}